-- 107: Original BrillaPrep 4BI1 beta questions, part 1.
-- Original practice content; not official Pearson questions.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_001', 'topic_edx_4bi1_1', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which process releases energy from nutrients in all living organisms?', 'multiple_choice', '["A. Respiration","B. Photosynthesis","C. Excretion","D. Transpiration"]', 'A', 'Respiration transfers chemical energy from nutrients for cellular activities in organisms. Therefore the correct answer is A: Respiration.', 'easy', 1, 1, 90, 'st_edx_4bi1_1', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_002', 'topic_edx_4bi1_1', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which feature distinguishes plants from animals at the cellular level?', 'multiple_choice', '["A. Animal cells contain chloroplasts","B. Plant cells have cellulose cell walls","C. Plant cells lack nuclei","D. Animal cells have cellulose walls"]', 'B', 'Cellulose cell walls support plant cells; animal cells do not possess these walls. Therefore the correct answer is B: Plant cells have cellulose cell walls.', 'medium', 2, 2, 90, 'st_edx_4bi1_1', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_003', 'topic_edx_4bi1_1', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which organism is a fungus?', 'multiple_choice', '["A. Amoeba","B. Lactobacillus","C. Yeast","D. Moss"]', 'C', 'Yeast obtains nutrients heterotrophically and has the cellular organisation characteristic of fungi. Therefore the correct answer is C: Yeast.', 'hard', 1, 1, 90, 'st_edx_4bi1_1', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_004', 'topic_edx_4bi1_1', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which structure is present in bacteria but not as a membrane-bound organelle?', 'multiple_choice', '["A. A nucleus","B. Mitochondria","C. Chloroplasts","D. A circular chromosome in the cytoplasm"]', 'D', 'Bacterial DNA is circular and lies free in the cytoplasm because bacteria have no nucleus. Therefore the correct answer is D: A circular chromosome in the cytoplasm.', 'easy', 2, 2, 90, 'st_edx_4bi1_1', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_005', 'topic_edx_4bi1_1', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which statement about viruses is correct?', 'multiple_choice', '["A. They reproduce only inside living cells","B. They respire independently","C. They are made of many cells","D. They feed by photosynthesis"]', 'A', 'Viruses depend on host-cell machinery to copy their genetic material and make new particles. Therefore the correct answer is A: They reproduce only inside living cells.', 'medium', 3, 3, 90, 'st_edx_4bi1_1', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_006', 'topic_edx_4bi1_1', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which life process removes metabolic waste from an organism?', 'multiple_choice', '["A. Nutrition","B. Excretion","C. Growth","D. Sensitivity"]', 'B', 'Excretion removes toxic materials and products made by metabolism, such as carbon dioxide and urea. Therefore the correct answer is B: Excretion.', 'hard', 2, 2, 90, 'st_edx_4bi1_1', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_007', 'topic_edx_4bi1_1', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Why is binomial naming useful?', 'multiple_choice', '["A. It measures population size","B. It identifies an organism’s age","C. It gives each species a universal two-part name","D. It shows every evolutionary ancestor"]', 'C', 'A genus-and-species name lets scientists communicate about the same organism across languages. Therefore the correct answer is C: It gives each species a universal two-part name.', 'easy', 1, 1, 90, 'st_edx_4bi1_1', 'Explain', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_008', 'topic_edx_4bi1_1', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which feature is characteristic of protoctists?', 'multiple_choice', '["A. They always have cellulose walls","B. They are all multicellular animals","C. They contain no genetic material","D. They are eukaryotic and mostly single-celled"]', 'D', 'Protoctists have nuclei and other eukaryotic features, while many exist as single cells. Therefore the correct answer is D: They are eukaryotic and mostly single-celled.', 'medium', 2, 2, 90, 'st_edx_4bi1_1', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_009', 'topic_edx_4bi1_2', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which organelle is the main site of aerobic respiration?', 'multiple_choice', '["A. Mitochondrion","B. Ribosome","C. Vacuole","D. Cell wall"]', 'A', 'Aerobic respiration occurs mainly in mitochondria, releasing usable energy for cell processes. Therefore the correct answer is A: Mitochondrion.', 'hard', 1, 1, 90, 'st_edx_4bi1_2', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_010', 'topic_edx_4bi1_2', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Why does water enter a plant root hair cell from dilute soil solution?', 'multiple_choice', '["A. Active transport pumps water outward","B. The soil has higher water potential than the cell sap","C. The cell wall is completely impermeable","D. The soil has lower water potential"]', 'B', 'Water moves by osmosis from higher to lower water potential across the partially permeable membrane. Therefore the correct answer is B: The soil has higher water potential than the cell sap.', 'easy', 3, 3, 90, 'st_edx_4bi1_2', 'Explain', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_011', 'topic_edx_4bi1_2', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'What is the role of amylase in digestion?', 'multiple_choice', '["A. It breaks protein into amino acids","B. It emulsifies lipids","C. It breaks starch into smaller sugars","D. It absorbs glucose into blood"]', 'C', 'Amylase catalyses hydrolysis of starch, producing smaller carbohydrate molecules such as maltose. Therefore the correct answer is C: It breaks starch into smaller sugars.', 'medium', 1, 1, 90, 'st_edx_4bi1_2', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_012', 'topic_edx_4bi1_2', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which blood vessel carries oxygenated blood from the lungs to the heart?', 'multiple_choice', '["A. Pulmonary artery","B. Vena cava","C. Hepatic portal vein","D. Pulmonary vein"]', 'D', 'The pulmonary vein returns oxygen-rich blood from lung capillaries to the left atrium. Therefore the correct answer is D: Pulmonary vein.', 'hard', 2, 2, 90, 'st_edx_4bi1_2', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_013', 'topic_edx_4bi1_2', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'What causes air to enter the lungs during inhalation?', 'multiple_choice', '["A. Thoracic volume rises and pressure falls below atmospheric pressure","B. Thoracic pressure rises above atmospheric pressure","C. The diaphragm relaxes upward","D. The ribs move down and inward"]', 'A', 'Contraction of the diaphragm and external intercostals expands the chest and lowers its pressure. Therefore the correct answer is A: Thoracic volume rises and pressure falls below atmospheric pressure.', 'easy', 1, 1, 90, 'st_edx_4bi1_2', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_014', 'topic_edx_4bi1_2', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which response helps lower body temperature?', 'multiple_choice', '["A. Shivering and vasoconstriction","B. Sweating and skin vasodilation","C. Reduced sweat production","D. Hair erection"]', 'B', 'Evaporation of sweat removes heat while wider skin arterioles increase heat transfer at the surface. Therefore the correct answer is B: Sweating and skin vasodilation.', 'medium', 2, 2, 90, 'st_edx_4bi1_2', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_015', 'topic_edx_4bi1_2', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'What is the function of xylem vessels?', 'multiple_choice', '["A. Transport sucrose only","B. Carry nerve impulses","C. Transport water and mineral ions and provide support","D. Produce antibodies"]', 'C', 'Lignified xylem forms continuous tubes that carry water upward and strengthen the plant. Therefore the correct answer is C: Transport water and mineral ions and provide support.', 'hard', 3, 3, 90, 'st_edx_4bi1_2', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_016', 'topic_edx_4bi1_2', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which hormone lowers blood glucose concentration?', 'multiple_choice', '["A. Glucagon","B. Adrenaline","C. Testosterone","D. Insulin"]', 'D', 'Insulin promotes glucose uptake and glycogen formation, reducing the glucose concentration in blood. Therefore the correct answer is D: Insulin.', 'easy', 2, 2, 90, 'st_edx_4bi1_2', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_017', 'topic_edx_4bi1_3', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Where does fertilisation normally occur in the human female reproductive system?', 'multiple_choice', '["A. Oviduct","B. Uterus","C. Ovary","D. Cervix"]', 'A', 'An ovum and sperm usually fuse in the oviduct before the early embryo reaches the uterus. Therefore the correct answer is A: Oviduct.', 'medium', 1, 1, 90, 'st_edx_4bi1_3', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_018', 'topic_edx_4bi1_3', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Which process produces genetically different gametes?', 'multiple_choice', '["A. Mitosis","B. Meiosis","C. Binary fission","D. Cloning"]', 'B', 'Meiosis halves chromosome number and creates variation through independent assortment and crossing over. Therefore the correct answer is B: Meiosis.', 'hard', 2, 2, 90, 'st_edx_4bi1_3', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_019', 'topic_edx_4bi1_3', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'Two heterozygous parents have genotypes Bb and Bb. What is the chance of bb?', 'multiple_choice', '["A. 0%","B. 50%","C. 25%","D. 75%"]', 'C', 'The possible offspring genotypes are BB, Bb, Bb and bb, so one of four is bb. Therefore the correct answer is C: 25%.', 'easy', 1, 1, 90, 'st_edx_4bi1_3', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4bi1_b001_020', 'topic_edx_4bi1_3', 'subj_edexcel_igcse_biology', 'edexcel_igcse', 'In molecular genetics, what is a gene?', 'multiple_choice', '["A. A complete set of chromosomes","B. Any visible characteristic","C. A type of cell membrane","D. A length of DNA that codes for a functional product"]', 'D', 'A gene is a nucleotide sequence carrying information used to make a protein or functional RNA. Therefore the correct answer is D: A length of DNA that codes for a functional product.', 'medium', 3, 3, 90, 'st_edx_4bi1_3', 'Identify', 'AO2', 'board_edexcel');
